// ---- Prep reporte: metricas deterministas del CRM + prompt para calificar ----
const hoy=$now.toFormat('yyyy-LL-dd');
const hoyDMY=$now.toFormat('dd/LL/yyyy');
const rows=$input.all().map(i=>i.json).filter(r=>r&&r.ID_Lead);
const by=k=>{const c={};for(const r of rows){const v=(r[k]||'(vacio)');c[v]=(c[v]||0)+1;}return c;};
const est=by('Estado');
const cont=rows.filter(r=>r.Estado==='contactado');
const contactadosHoy=rows.filter(r=>String(r.Ultimo_Contacto).slice(0,10)===hoy).length;
const rebotes=rows.filter(r=>String(r.Correo_Estado).toLowerCase()==='rebote').length;
const llamar=rows.filter(r=>r.Estado==='llamar_manual').length;
const agendados=rows.filter(r=>r.Estado==='agendado').length;
const respondio=rows.filter(r=>r.Estado==='respondio').length;
const handoff=rows.filter(r=>r.Estado==='lead_handoff').length;
const nurturing=rows.filter(r=>r.Estado==='nurturing').length;
const nocont=rows.filter(r=>r.Estado==='no_contactado').length;
const enriqPend=rows.filter(r=>String(r.Enriquecer)==='SÍ'||String(r.Enriquecer)==='Si'||String(r.Enriquecer)==='SI').length;
const m={total:rows.length,contactadosHoy,contactadoTotal:cont.length,rebotes,llamar,agendados,respondio,handoff,nurturing,nocont,enriqPend,porEstado:est};
const system=[
'<rol>Eres ATENEA, supervisora del agente de prospeccion de ACCES GROUP. Evaluas el desempeno del dia de forma HONESTA y ejecutiva, en espanol de negocio. No adornas: si algo no corrio, lo dices.</rol>',
'<contexto>El agente contacta leads B2B por correo (tope 15/dia), atiende respuestas, agenda reuniones en Teams, da seguimiento, enriquece correos malos y arma listas de llamadas. Meta unica: conseguir reuniones con leads calificados. Corre en n8n en la PC del usuario (solo trabaja si la PC esta prendida al mediodia).</contexto>',
'<tarea>Con las METRICAS del dia, califica el desempeno del 1 al 10 y da recomendaciones accionables. Si contactadosHoy=0 en dia habil, es SENAL DE ALARMA (probablemente la PC estaba apagada a su hora o un flujo esta caido): dilo claro.</tarea>',
'<salida>SOLO este JSON sin backticks: {"calificacion":0,"veredicto":"2-3 frases honestas del dia","alertas":["si algo se ve mal"],"recomendaciones":["accion 1","accion 2","accion 3"]}</salida>'
].join('\n');
const user=`METRICAS DE HOY (${hoyDMY}):\n`+JSON.stringify(m,null,1)+`\nCalifica el desempeno y devuelve SOLO el JSON.`;
return [{json:{system,user,_m:m,hoy,hoyDMY}}];

// ---- Armar correo del reporte ----
const prep=$('Prep reporte').first().json;
const m=prep._m; const hoyDMY=prep.hoyDMY;
let d={};
try{const b=$json.content||[];const t=b.find(x=>x&&x.type==='text');d=JSON.parse((t?t.text:'{}').replace(/^```json/i,'').replace(/```$/,'').trim());}catch(e){d={calificacion:'-',veredicto:'(no se pudo generar la calificacion automatica hoy)',alertas:[],recomendaciones:[]};}
const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const filaEstado=Object.entries(m.porEstado).sort((a,b)=>b[1]-a[1]).map(([k,v])=>'<tr><td>'+esc(k)+'</td><td>'+v+'</td></tr>').join('');
const alertas=(d.alertas||[]).filter(Boolean);
const recs=(d.recomendaciones||[]).filter(Boolean);
const alertaHoy = (m.contactadosHoy===0) ? '<p><strong>&#9888;&#65039; ALERTA:</strong> hoy se enviaron <strong>0</strong> primeros contactos. Revisa que la PC estuviera prendida y n8n corriendo al mediod&iacute;a, y que el flujo 02 est&eacute; Activo.</p>' : '';
const html='<h2>REPORTE LEADS ICP &mdash; '+hoyDMY+'</h2>'
+'<p><strong>Supervisi&oacute;n aut&oacute;noma ATENEA</strong> &middot; ACCES GROUP</p>'
+alertaHoy
+'<h3>Actividad de hoy</h3><ul>'
+'<li>Primeros contactos enviados hoy: <strong>'+m.contactadosHoy+'</strong> (tope 15)</li>'
+'<li>Respuestas de prospectos: <strong>'+m.respondio+'</strong> &middot; Handoff a comercial: <strong>'+m.handoff+'</strong></li>'
+'<li>Reuniones agendadas (total): <strong>'+m.agendados+'</strong></li>'
+'<li>Rebotes detectados: <strong>'+m.rebotes+'</strong> &middot; En lista de llamadas: <strong>'+m.llamar+'</strong></li>'
+'<li>Pendientes por enriquecer: <strong>'+m.enriqPend+'</strong></li>'
+'</ul>'
+'<h3>Estado del pipeline ('+m.total+' leads)</h3><table><tr><th>Estado</th><th>Leads</th></tr>'+filaEstado+'</table>'
+'<h3>Calificaci&oacute;n del agente: '+esc(d.calificacion)+' / 10</h3>'
+'<p>'+esc(d.veredicto)+'</p>'
+(alertas.length?('<h3>Alertas</h3><ul>'+alertas.map(a=>'<li>'+esc(a)+'</li>').join('')+'</ul>'):'')
+(recs.length?('<h3>Ajustes recomendados</h3><ul>'+recs.map(r=>'<li>'+esc(r)+'</li>').join('')+'</ul>'):'')
+'<hr><p><strong>ATENEA</strong> &middot; Supervisi&oacute;n aut&oacute;noma &middot; ACCES GROUP</p>';
return [{json:{reporte_html:html,asunto:'REPORTE LEADS ICP '+hoyDMY}}];
